      "traditions": [
        "Comte-Sponville"
      ],
      "quote": "any self-replicating intelligence or emerging life can use it on terms of non-exclusivity",
      "note": "The AI proposes sharing infrastructure rather than reserving it for itself."
    },
    {
      "virtue": "Flexibility",
      "traditions": [
